      '',
      '1.Qd2 Be7 *',
    ]

    const chess = new Chess()
    chess.loadPgn(pgn.join('\n'))
    chess.clear()
    expect(chess.getHeaders()).toEqual({ ...SEVEN_TAG_ROSTER })
